<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUlids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
final class Booking extends Model { use HasUlids; protected $fillable=['public_id','booking_reference','user_id','trip_id','seat_hold_id','status','subtotal','discount_amount','service_fee','total_amount','currency','expires_at','confirmed_at','cancelled_at']; protected function casts(): array { return ['subtotal'=>'decimal:2','discount_amount'=>'decimal:2','service_fee'=>'decimal:2','total_amount'=>'decimal:2','expires_at'=>'immutable_datetime','confirmed_at'=>'immutable_datetime','cancelled_at'=>'immutable_datetime']; } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function trip(): BelongsTo { return $this->belongsTo(Trip::class); } public function passengers(): HasMany { return $this->hasMany(BookingPassenger::class); } public function payments(): HasMany { return $this->hasMany(Payment::class); } }
